create extension if not exists pgcrypto;
create table users (id uuid primary key default gen_random_uuid(), clerk_id varchar(120) not null unique, email varchar(255) not null, display_name varchar(255), role varchar(16) not null check (role in ('ADMIN','STAFF')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table items (id uuid primary key default gen_random_uuid(), name varchar(255) not null, sku varchar(80) not null unique, barcode varchar(120) unique, category varchar(120), unit varchar(32) not null default 'each', quantity integer not null default 0 check (quantity >= 0), low_stock_threshold integer not null default 0 check (low_stock_threshold >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index idx_items_barcode on items(barcode); create index idx_items_sku on items(sku);
create table stock_transactions (id uuid primary key default gen_random_uuid(), item_id uuid not null references items(id), type varchar(3) not null check(type in ('IN','OUT')), quantity integer not null check(quantity > 0), note text, performed_by uuid references users(id), created_at timestamptz not null default now()); create index idx_tx_created_at on stock_transactions(created_at);
create table alerts (id uuid primary key default gen_random_uuid(), item_id uuid not null references items(id), status varchar(16) not null default 'OPEN' check(status in ('OPEN','ACKNOWLEDGED','RESOLVED')), message text not null, created_at timestamptz not null default now(), resolved_at timestamptz); create unique index one_open_alert_per_item on alerts(item_id) where status <> 'RESOLVED';
